/* cppi::a2981f9ec003183c25792b07225766dd10190d1a7ec0c28c741c59b6ee02c79a */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-06-04' and end_date = '2025-06-04')
and start_date = '2025-06-04' and end_date = '2025-06-04'

/* cppi::55761a07da32180b8820459fe0d29e0d0f9d253bf241d70a52f46a788af33e7f */
with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from ( select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2 )
    )--, cslxhis as(
    select his.*
    from df_trusted_prod.mds_csl_daily_history his
        join cslDates cDates on his.business_date = cDates.business_dt
        where his.business_date = cDates.previous_business_dt
        ORDER BY his.id_cppibsec

